  1→package checkpoint
  2→
  3→import (
  4→	"fmt"
  5→
  6→	"github.com/go-git/go-git/v6"
  7→	"github.com/go-git/go-git/v6/plumbing"
  8→	"github.com/go-git/go-git/v6/plumbing/object"
  9→)
 10→
 11→// V2GitStore provides checkpoint storage operations for the v2 ref layout.
 12→// It writes to two custom refs under refs/entire/:
 13→//   - /main: permanent metadata + compact transcripts
 14→//   - /full/current: active generation of raw transcripts
 15→//
 16→// V2GitStore is separate from GitStore (v1) to keep concerns isolated
 17→// and simplify future v1 removal. It composes GitStore internally to
 18→// reuse ref-agnostic entry-building helpers (tree surgery, session
 19→// indexing, summary aggregation).
 20→type V2GitStore struct {
 21→	repo *git.Repository
 22→	gs   *GitStore // shared entry-building helpers (same package)
 23→
 24→	// maxCheckpointsPerGeneration overrides the rotation threshold for testing.
 25→	// Zero means use DefaultMaxCheckpointsPerGeneration.
 26→	maxCheckpointsPerGeneration int
 27→
 28→	// FetchRemote is the git remote used for fetch-on-demand operations (e.g.,
 29→	// fetching /full/* refs during entire resume). Defaults to "origin".
 30→	// Set to the checkpoint remote URL when checkpoint_remote is configured.
 31→	FetchRemote string
 32→}
 33→
 34→// maxCheckpoints returns the effective rotation threshold.
 35→func (s *V2GitStore) maxCheckpoints() int {
 36→	if s.maxCheckpointsPerGeneration > 0 {
 37→		return s.maxCheckpointsPerGeneration
 38→	}
 39→	return DefaultMaxCheckpointsPerGeneration
 40→}
 41→
 42→// NewV2GitStore creates a new v2 checkpoint store backed by the given git repository.
 43→// fetchRemote is the git remote used for fetch-on-demand operations (e.g., fetching
 44→// /full/* refs during entire resume). Pass "origin" or the checkpoint remote URL.
 45→func NewV2GitStore(repo *git.Repository, fetchRemote string) *V2GitStore {
 46→	if fetchRemote == "" {
 47→		fetchRemote = "origin"
 48→	}
 49→	return &V2GitStore{
 50→		repo:        repo,
 51→		gs:          &GitStore{repo: repo},
 52→		FetchRemote: fetchRemote,
 53→	}
 54→}
 55→
 56→// ensureRef ensures that a custom ref exists, creating an orphan commit
 57→// with an empty tree if it does not.
 58→func (s *V2GitStore) ensureRef(refName plumbing.ReferenceName) error {
 59→	_, err := s.repo.Reference(refName, true)
 60→	if err == nil {
 61→		return nil // Already exists
 62→	}
 63→
 64→	emptyTreeHash, err := BuildTreeFromEntries(s.repo, make(map[string]object.TreeEntry))
 65→	if err != nil {
 66→		return fmt.Errorf("failed to build empty tree: %w", err)
 67→	}
 68→
 69→	authorName, authorEmail := GetGitAuthorFromRepo(s.repo)
 70→	commitHash, err := CreateCommit(s.repo, emptyTreeHash, plumbing.ZeroHash, "Initialize v2 ref", authorName, authorEmail)
 71→	if err != nil {
 72→		return fmt.Errorf("failed to create initial commit: %w", err)
 73→	}
 74→
 75→	ref := plumbing.NewHashReference(refName, commitHash)
 76→	if err := s.repo.Storer.SetReference(ref); err != nil {
 77→		return fmt.Errorf("failed to set ref %s: %w", refName, err)
 78→	}
 79→
 80→	return nil
 81→}
 82→
 83→// GetRefState returns the parent commit hash and root tree hash for a ref.
 84→func (s *V2GitStore) GetRefState(refName plumbing.ReferenceName) (parentHash, treeHash plumbing.Hash, err error) {
 85→	ref, err := s.repo.Reference(refName, true)
 86→	if err != nil {
 87→		return plumbing.ZeroHash, plumbing.ZeroHash, fmt.Errorf("ref %s not found: %w", refName, err)
 88→	}
 89→
 90→	commit, err := s.repo.CommitObject(ref.Hash())
 91→	if err != nil {
 92→		return plumbing.ZeroHash, plumbing.ZeroHash, fmt.Errorf("failed to get commit for ref %s: %w", refName, err)
 93→	}
 94→
 95→	return ref.Hash(), commit.TreeHash, nil
 96→}
 97→
 98→// updateRef creates a new commit on a ref with the given tree, updating the ref to point to it.
 99→func (s *V2GitStore) updateRef(refName plumbing.ReferenceName, treeHash, parentHash plumbing.Hash, message, authorName, authorEmail string) error {
100→	commitHash, err := CreateCommit(s.repo, treeHash, parentHash, message, authorName, authorEmail)
101→	if err != nil {
102→		return fmt.Errorf("failed to create commit: %w", err)
103→	}
104→
105→	ref := plumbing.NewHashReference(refName, commitHash)
106→	if err := s.repo.Storer.SetReference(ref); err != nil {
107→		return fmt.Errorf("failed to update ref %s: %w", refName, err)
108→	}
109→
110→	return nil
111→}
