237→// writeCommittedMain writes metadata entries to the /main ref.
238→// This includes session metadata and prompts — but NOT the raw transcript
239→// (full.jsonl) or content hash (content_hash.txt), which go to /full/current.
240→// Returns the session index used, so the caller can pass it to writeCommittedFullTranscript.
241→func (s *V2GitStore) writeCommittedMain(ctx context.Context, opts WriteCommittedOptions) (int, error) {
242→	refName := plumbing.ReferenceName(paths.V2MainRefName)
243→	if err := s.ensureRef(refName); err != nil {
244→		return 0, fmt.Errorf("failed to ensure /main ref: %w", err)
245→	}
246→
247→	parentHash, rootTreeHash, err := s.GetRefState(refName)
248→	if err != nil {
249→		return 0, err
250→	}
251→
252→	basePath := opts.CheckpointID.Path() + "/"
253→	checkpointPath := opts.CheckpointID.Path()
254→
255→	// Read existing entries at this checkpoint's shard path
256→	entries, err := s.gs.flattenCheckpointEntries(rootTreeHash, checkpointPath)
257→	if err != nil {
258→		return 0, err
259→	}
260→
261→	// Build main session entries (metadata, prompts — no transcript or content hash)
262→	sessionIndex, err := s.writeMainCheckpointEntries(ctx, opts, basePath, entries)
263→	if err != nil {
264→		return 0, err
265→	}
266→
267→	// Splice entries into root tree
268→	newTreeHash, err := s.gs.spliceCheckpointSubtree(rootTreeHash, opts.CheckpointID, basePath, entries)
269→	if err != nil {
270→		return 0, err
271→	}
272→
273→	commitMsg := fmt.Sprintf("Checkpoint: %s\n", opts.CheckpointID)
274→	if err := s.updateRef(refName, newTreeHash, parentHash, commitMsg, opts.AuthorName, opts.AuthorEmail); err != nil {
275→		return 0, err
276→	}
277→	return sessionIndex, nil
278→}
279→
280→// writeMainCheckpointEntries orchestrates writing session data to the /main ref.
281→// It mirrors GitStore.writeStandardCheckpointEntries but excludes raw transcript blobs.
282→// Returns the session index used, for coordination with writeCommittedFullTranscript.
283→func (s *V2GitStore) writeMainCheckpointEntries(ctx context.Context, opts WriteCommittedOptions, basePath string, entries map[string]object.TreeEntry) (int, error) {
284→	// Read existing summary to get current session count
285→	var existingSummary *CheckpointSummary
286→	metadataPath := basePath + paths.MetadataFileName
287→	if entry, exists := entries[metadataPath]; exists {
288→		existing, err := readJSONFromBlob[CheckpointSummary](s.repo, entry.Hash)
289→		if err == nil {
290→			existingSummary = existing
291→		}
292→	}
293→
294→	// Determine session index
295→	sessionIndex := s.gs.findSessionIndex(ctx, basePath, existingSummary, entries, opts.SessionID)
296→
297→	// Write session files (metadata and prompts — no transcript or content hash)
298→	sessionPath := fmt.Sprintf("%s%d/", basePath, sessionIndex)
299→	sessionFilePaths, err := s.writeMainSessionToSubdirectory(opts, sessionPath, entries)
300→	if err != nil {
301→		return 0, err
302→	}
303→
304→	// Build the sessions array
305→	var sessions []SessionFilePaths
306→	if existingSummary != nil {
307→		sessions = make([]SessionFilePaths, max(len(existingSummary.Sessions), sessionIndex+1))
308→		copy(sessions, existingSummary.Sessions)
309→	} else {
310→		sessions = make([]SessionFilePaths, 1)
311→	}
312→	sessions[sessionIndex] = sessionFilePaths
313→
314→	// Write root CheckpointSummary
315→	if err := s.gs.writeCheckpointSummary(opts, basePath, entries, sessions); err != nil {
316→		return 0, err
317→	}
318→	return sessionIndex, nil
319→}
320→
321→// writeMainSessionToSubdirectory writes a single session's metadata, prompts,
322→// and compact transcript to a session subdirectory (0/, 1/, 2/, … indexed by
323→// session order within the checkpoint). The raw transcript (full.jsonl) and its
324→// content hash (content_hash.txt) go to /full/current, not here.
325→func (s *V2GitStore) writeMainSessionToSubdirectory(opts WriteCommittedOptions, sessionPath string, entries map[string]object.TreeEntry) (SessionFilePaths, error) {
326→	filePaths := SessionFilePaths{}
327→
328→	// Clear existing entries at this session path
329→	for key := range entries {
330→		if strings.HasPrefix(key, sessionPath) {
331→			delete(entries, key)
332→		}
333→	}
334→
335→	// Write prompts
336→	if len(opts.Prompts) > 0 {
337→		promptContent := redact.String(JoinPrompts(opts.Prompts))
338→		blobHash, err := CreateBlobFromContent(s.repo, []byte(promptContent))
339→		if err != nil {
340→			return filePaths, err
341→		}
342→		entries[sessionPath+paths.PromptFileName] = object.TreeEntry{
343→			Name: sessionPath + paths.PromptFileName,
344→			Mode: filemode.Regular,
345→			Hash: blobHash,
346→		}
347→		filePaths.Prompt = "/" + sessionPath + paths.PromptFileName
348→	}
349→
350→	// Write compact transcript (transcript.jsonl) + hash if provided
351→	if len(opts.CompactTranscript) > 0 {
352→		blobHash, err := CreateBlobFromContent(s.repo, opts.CompactTranscript)
353→		if err != nil {
354→			return filePaths, fmt.Errorf("failed to create compact transcript blob: %w", err)
355→		}
356→		entries[sessionPath+paths.CompactTranscriptFileName] = object.TreeEntry{
357→			Name: sessionPath + paths.CompactTranscriptFileName,
358→			Mode: filemode.Regular,
359→			Hash: blobHash,
360→		}
361→		filePaths.Transcript = "/" + sessionPath + paths.CompactTranscriptFileName
362→
363→		if err := s.writeCompactTranscriptHash(opts.CompactTranscript, sessionPath, entries); err != nil {
364→			return filePaths, fmt.Errorf("failed to write compact transcript hash: %w", err)
365→		}
366→		filePaths.ContentHash = "/" + sessionPath + paths.CompactTranscriptHashFileName
367→	}
368→
369→	// Write session metadata
370→	sessionMetadata := CommittedMetadata{
371→		CheckpointID:                opts.CheckpointID,
372→		SessionID:                   opts.SessionID,
373→		Strategy:                    opts.Strategy,
374→		CreatedAt:                   time.Now().UTC(),
375→		Branch:                      opts.Branch,
376→		CheckpointsCount:            opts.CheckpointsCount,
377→		FilesTouched:                opts.FilesTouched,
378→		Agent:                       opts.Agent,
379→		Model:                       opts.Model,
380→		TurnID:                      opts.TurnID,
381→		IsTask:                      opts.IsTask,
382→		ToolUseID:                   opts.ToolUseID,
383→		TranscriptIdentifierAtStart: opts.TranscriptIdentifierAtStart,
384→		CheckpointTranscriptStart:   opts.CheckpointTranscriptStart,
385→		TokenUsage:                  opts.TokenUsage,
386→		SessionMetrics:              opts.SessionMetrics,
387→		InitialAttribution:          opts.InitialAttribution,
388→		PromptAttributions:          opts.PromptAttributionsJSON,
389→		Summary:                     redactSummary(opts.Summary),
390→		CLIVersion:                  versioninfo.Version,
391→	}
392→
393→	metadataJSON, err := jsonutil.MarshalIndentWithNewline(sessionMetadata, "", "  ")
394→	if err != nil {
395→		return filePaths, fmt.Errorf("failed to marshal session metadata: %w", err)
396→	}
397→	metadataHash, err := CreateBlobFromContent(s.repo, metadataJSON)
398→	if err != nil {
399→		return filePaths, err
400→	}
401→	entries[sessionPath+paths.MetadataFileName] = object.TreeEntry{
402→		Name: sessionPath + paths.MetadataFileName,
403→		Mode: filemode.Regular,
404→		Hash: metadataHash,
405→	}
406→	filePaths.Metadata = "/" + sessionPath + paths.MetadataFileName
407→
408→	return filePaths, nil
409→}
