411→// writeContentHash computes and writes the content hash for already-redacted transcript bytes.
412→func (s *V2GitStore) writeContentHash(redactedTranscript []byte, sessionPath string, entries map[string]object.TreeEntry) error {
413→	contentHash := fmt.Sprintf("sha256:%x", sha256.Sum256(redactedTranscript))
414→	hashBlob, err := CreateBlobFromContent(s.repo, []byte(contentHash))
415→	if err != nil {
416→		return err
417→	}
418→	entries[sessionPath+paths.ContentHashFileName] = object.TreeEntry{
419→		Name: sessionPath + paths.ContentHashFileName,
420→		Mode: filemode.Regular,
421→		Hash: hashBlob,
422→	}
423→	return nil
424→}
425→
426→// writeCompactTranscriptHash computes and writes the SHA-256 hash of the compact transcript.
427→func (s *V2GitStore) writeCompactTranscriptHash(compactTranscript []byte, sessionPath string, entries map[string]object.TreeEntry) error {
428→	hash := fmt.Sprintf("sha256:%x", sha256.Sum256(compactTranscript))
429→	blobHash, err := CreateBlobFromContent(s.repo, []byte(hash))
430→	if err != nil {
431→		return err
432→	}
433→	entries[sessionPath+paths.CompactTranscriptHashFileName] = object.TreeEntry{
434→		Name: sessionPath + paths.CompactTranscriptHashFileName,
435→		Mode: filemode.Regular,
436→		Hash: blobHash,
437→	}
438→	return nil
439→}
