441→// writeCommittedFullTranscript writes the raw transcript to the /full/current ref.
442→// Transcripts accumulate across checkpoints — each write splices into the existing
443→// tree. Generation metadata (generation.json) at the tree root is updated on every
444→// write with the new checkpoint ID and timestamps.
445→//
446→// sessionIndex is the session slot (0-based), determined by the caller to stay
447→// consistent with the /main ref's session numbering.
448→// This is a no-op if opts.Transcript is empty (and opts.TranscriptPath is unset).
449→func (s *V2GitStore) writeCommittedFullTranscript(ctx context.Context, opts WriteCommittedOptions, sessionIndex int) error {
450→	transcript := opts.Transcript
451→	if len(transcript) == 0 && opts.TranscriptPath != "" {
452→		var readErr error
453→		transcript, readErr = os.ReadFile(opts.TranscriptPath)
454→		if readErr != nil {
455→			transcript = nil
456→		}
457→	}
458→	if len(transcript) == 0 {
459→		return nil // No transcript to write
460→	}
461→
462→	refName := plumbing.ReferenceName(paths.V2FullCurrentRefName)
463→	if err := s.ensureRef(refName); err != nil {
464→		return fmt.Errorf("failed to ensure /full/current ref: %w", err)
465→	}
466→
467→	parentHash, rootTreeHash, err := s.GetRefState(refName)
468→	if err != nil {
469→		return err
470→	}
471→
472→	basePath := opts.CheckpointID.Path() + "/"
473→	checkpointPath := opts.CheckpointID.Path()
474→	sessionPath := fmt.Sprintf("%s%d/", basePath, sessionIndex)
475→
476→	// Read existing entries at this checkpoint's shard path
477→	entries, err := s.gs.flattenCheckpointEntries(rootTreeHash, checkpointPath)
478→	if err != nil {
479→		return err
480→	}
481→
482→	// Clear existing entries at this session path before writing new ones
483→	for key := range entries {
484→		if strings.HasPrefix(key, sessionPath) {
485→			delete(entries, key)
486→		}
487→	}
488→
489→	redactedTranscript, err := s.writeTranscriptBlobs(ctx, transcript, opts.Agent, sessionPath, entries)
490→	if err != nil {
491→		return err
492→	}
493→
494→	if err := s.writeContentHash(redactedTranscript, sessionPath, entries); err != nil {
495→		return err
496→	}
497→
498→	// Splice checkpoint data into the root tree (preserves other checkpoints' transcripts)
499→	newTreeHash, err := s.gs.spliceCheckpointSubtree(rootTreeHash, opts.CheckpointID, basePath, entries)
500→	if err != nil {
501→		return err
502→	}
503→
504→	commitMsg := fmt.Sprintf("Checkpoint: %s\n", opts.CheckpointID)
505→	if err := s.updateRef(refName, newTreeHash, parentHash, commitMsg, opts.AuthorName, opts.AuthorEmail); err != nil {
506→		return err
507→	}
508→
509→	// Check if rotation is needed after successful write.
510→	// Count checkpoints by walking the tree (no generation.json on /full/current).
511→	checkpointCount, countErr := s.CountCheckpointsInTree(newTreeHash)
512→	if countErr != nil {
513→		logging.Warn(ctx, "failed to count checkpoints for rotation check",
514→			slog.String("error", countErr.Error()),
515→		)
516→		return nil
517→	}
518→	if checkpointCount >= s.maxCheckpoints() {
519→		if rotErr := s.rotateGeneration(ctx); rotErr != nil {
520→			logging.Warn(ctx, "generation rotation failed",
521→				slog.String("error", rotErr.Error()),
522→				slog.Int("checkpoint_count", checkpointCount),
523→			)
524→			// Non-fatal: rotation failure doesn't invalidate the write
525→		}
526→	}
527→
528→	return nil
529→}
